import { AfterViewInit, Component, ElementRef, QueryList, ViewChildren } from '@angular/core';

interface CounterButton {
  id: number;
  count: number;
}

type NavigationKey = 'ArrowUp' | 'ArrowDown' | 'Home' | 'End';

const NAVIGATION_KEYS: NavigationKey[] = ['ArrowUp', 'ArrowDown', 'Home', 'End'];

@Component({
  selector: 'app-root',
  standalone: true,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements AfterViewInit {
  @ViewChildren('counterButton') counterButtons!: QueryList<ElementRef<HTMLButtonElement>>;

  readonly minLimit = 1;
  readonly maxLimit = 10;
  readonly defaultLimit = 5;

  buttons: CounterButton[] = [{ id: 1, count: 0 }];
  limit = this.defaultLimit;
  focusId = 1;

  private nextId = 2;
  private pendingFocusId: number | null = null;

  ngAfterViewInit(): void {
    this.counterButtons.changes.subscribe(() => this.restorePendingFocus());
  }

  get combinedValue(): number {
    return this.buttons.reduce((sum, button) => sum + button.count, 0);
  }

  get statusText(): string {
    return 'Counters: ' + this.buttons.length + ' of ' + this.limit
      + '. Combined value: ' + this.combinedValue + '.';
  }

  get isInitial(): boolean {
    return this.limit === this.defaultLimit
      && this.buttons.length === 1
      && this.buttons[0].id === 1
      && this.buttons[0].count === 0;
  }

  counterRowId(id: number): string {
    return 'counter-row-' + id;
  }

  counterButtonId(id: number): string {
    return 'counter-button-' + id;
  }

  removeButtonId(id: number): string {
    return 'remove-counter-' + id;
  }

  counterLabel(button: CounterButton): string {
    return 'Counter ' + button.id + ', value ' + button.count;
  }

  removeCounterLabel(id: number): string {
    return 'Remove counter ' + id;
  }

  onCounterFocus(id: number): void {
    this.focusId = id;
  }

  onClick(id: number): void {
    const updated = this.buttons.map((button) => (
      button.id === id ? { ...button, count: button.count + 1 } : button
    ));

    if (this.buttons.length < this.limit) {
      updated.push({ id: this.nextId, count: 0 });
      this.nextId += 1;
    }

    this.focusId = id;
    this.buttons = updated;
  }

  removeCounter(id: number): void {
    if (this.buttons.length === 1) return;
    const removedIndex = this.buttons.findIndex((button) => button.id === id);
    if (removedIndex < 0) return;

    const survivors = this.buttons.filter((button) => button.id !== id);
    const targetIndex = Math.min(removedIndex, survivors.length - 1);
    const targetId = survivors[targetIndex].id;

    this.pendingFocusId = targetId;
    this.focusId = targetId;
    this.buttons = survivors;
  }

  onLimitInput(raw: string): void {
    const parsed = Number(raw);
    const nextLimit = Number.isFinite(parsed)
      ? Math.min(this.maxLimit, Math.max(this.minLimit, Math.trunc(parsed)))
      : this.minLimit;
    const normalized = this.buttons.slice(0, nextLimit);

    this.limit = nextLimit;
    this.buttons = normalized;
    if (!normalized.some((button) => button.id === this.focusId)) {
      this.focusId = normalized[normalized.length - 1].id;
    }
  }

  resetCounters(): void {
    this.pendingFocusId = null;
    this.nextId = 2;
    this.limit = this.defaultLimit;
    this.buttons = [{ id: 1, count: 0 }];
    this.focusId = 1;
  }

  onCounterKeydown(event: KeyboardEvent, id: number): void {
    const key = event.key as NavigationKey;
    if (!NAVIGATION_KEYS.includes(key)) return;

    event.preventDefault();
    const currentIndex = this.buttons.findIndex((button) => button.id === id);
    if (currentIndex < 0) return;

    let targetIndex = currentIndex;
    if (key === 'ArrowUp') {
      targetIndex = (currentIndex + this.buttons.length - 1) % this.buttons.length;
    } else if (key === 'ArrowDown') {
      targetIndex = (currentIndex + 1) % this.buttons.length;
    } else if (key === 'Home') {
      targetIndex = 0;
    } else if (key === 'End') {
      targetIndex = this.buttons.length - 1;
    }

    this.focusCounter(this.buttons[targetIndex].id);
  }

  private restorePendingFocus(): void {
    if (this.pendingFocusId === null) return;
    const targetId = this.pendingFocusId;
    this.pendingFocusId = null;
    this.focusCounter(targetId);
  }

  private focusCounter(id: number): void {
    this.focusId = id;
    this.counterButtons
      .find((entry) => entry.nativeElement.id === this.counterButtonId(id))
      ?.nativeElement.focus();
  }
}

