  min-height: 100vh;
  padding: 24px;
  display: grid;
  place-items: center;
  color: #e5e7eb;
}

.card {
  width: 100%;
  max-width: 620px;
  min-width: 0;
  padding: 18px;
  display: grid;
  gap: 14px;
  border: 1px solid #1f2937;
  border-radius: 16px;
  background: #0b1020;
}

h1 {
  margin: 0;
  font-size: 21px;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 13px;
  line-height: 1.5;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 10px;
}

.limit-control {
  display: grid;
  gap: 6px;
  color: #cbd5e1;
  font-size: 12px;
}

.limit-control input {
  width: 110px;
  padding: 9px 10px;
  border: 1px solid #374151;
  border-radius: 10px;
  background: #0a0f1e;
  color: #e5e7eb;
}

.reset-button,
.remove-button,
.counter-button {
  border: 1px solid #374151;
  border-radius: 10px;
  color: #e5e7eb;
}

.reset-button,
.remove-button {
  padding: 9px 12px;
  background: #111827;
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.status {
  margin: 0;
  padding: 9px 11px;
  border: 1px solid #1f2937;
  border-radius: 10px;
  background: #0a0f1e;
