  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 9px;
}

.counter-button {
  min-width: 0;
  padding: 11px 14px;
  overflow-wrap: anywhere;
  background: #0a0f1e;
  text-align: left;
  cursor: pointer;
